<?php
namespace qqworld_collector\module\collect_filter; class stripslashes extends filter { public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { $item = str_replace('\n', "\n", $item); $item = str_replace('\t', "\t", $item); $item = str_replace('\r', "\r", $item); $item = stripslashes($item); return $item; } } ?>